INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "柴车", "aliases": ["柴車"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统5年（年号对照1440年）二月，柴车从陕西被召回任职，随即返乡省亲。", "biography": null, "status": "draft", "id": "55a68f00-9d84-5661-8c06-9bf22e7430c6"}, {"name": "黎利", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "黎利在交阯起兵。", "biography": null, "status": "draft", "id": "c3cb3b52-845e-5798-86eb-c3dfdd072dcd"}, {"name": "陈怀", "aliases": ["平乡伯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈怀率军在松潘作战。", "biography": null, "status": "draft", "id": "1f04c0a5-7d79-541c-ab2f-9938d38aad23"}, {"name": "金幼孜", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，金幼孜以翰林检讨身份入直文渊阁。", "biography": null, "status": "draft", "id": "01f8c39e-a2e9-5539-9e26-8926e64fc703"}, {"name": "陈瑄", "aliases": ["陈彦纯", "平江伯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈瑄以平江伯身份督办漕运并转运木材。", "biography": null, "status": "draft", "id": "104b6c7a-fa0b-5961-86b0-c745c1c2ad68"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明宣宗在南郊祭祀天地", "description": "宣德六年正月丁丑，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年正月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "123bf201-2760-56e5-8db8-f268b7ab0834"}, {"title": "本纪记有大雨雷电", "description": "宣德六年正月庚辰，《明史》本纪记当天大雨，并有雷电。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年正月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8764dbde-2731-574f-b6a4-d6f344828b34"}, {"title": "侍郎罗汝敬奉命督办陕西屯田", "description": "宣德六年二月丁酉，明廷命侍郎罗汝敬督办陕西屯田。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年二月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "908443b8-47b1-548f-807e-5a2dd5c57cdb"}, {"title": "明廷疏浚金龙口，引河水至徐州以便利漕运", "description": "宣德六年二月己亥，朝廷疏浚金龙口，引河水通到徐州，便利水路运粮。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年二月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0a05940f-1b93-5ee1-8bbb-104f7fdb8954"}, {"title": "明廷规定考察地方官由布政、按察两司开始", "description": "宣德六年三月乙亥，朝廷命吏部考察地方官时，先从布政使司和按察使司开始，并将做法定为法令。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年三月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dda61682-8561-5293-9995-34e1885ad9e5"}, {"title": "侍郎柴车奉命经办山西屯田", "description": "宣德六年四月己酉，明廷命侍郎柴车经办山西屯田。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "06fcf22e-74f8-5d3c-968b-79e9b4e219a4"}, {"title": "明廷诏令黎利暂掌安南国事", "description": "宣德六年六月己亥，明廷派使者向黎利传诏，命他暂时管理安南国事。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年六月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0db21e81-524d-5470-969d-e1708b0e69bc"}, {"title": "明廷审录在押囚犯", "description": "宣德六年七月己巳，朝廷审录在押囚犯。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年七月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0fa6abc7-cfa0-5a41-9232-7c47a0943fa8"}, {"title": "明廷准许朵颜三卫交易", "description": "宣德六年七月壬午，朝廷准许朵颜三卫进行市场交易。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年七月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7bd6638c-e02a-57d0-acd6-9c93708e7f85"}, {"title": "本纪记陈怀平息松潘战事", "description": "宣德六年十月甲辰，《明史》本纪记陈怀率军平息松潘一带与明廷的战事。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年十月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2b97b2ea-e828-51ef-9305-791ae0b5b637"}, {"title": "明廷开始由官军接运民户所缴粮食", "description": "宣德六年十一月丙子，朝廷开始命官军按兑运办法接运民户所缴粮食。", "start_year": 1431, "end_year": 1431, "time_original": "宣德六年十一月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e938819c-a6e4-53b8-ade9-4007cfefa163"}, {"title": "明廷派御史逮捕袁琦等宦官", "description": "宣德六年十一月乙酉，朝廷分别派御史前往逮捕被指贪婪残暴的宦官袁琦等人。", "start_year": 1432, "end_year": 1432, "time_original": "宣德六年十一月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8878b1a3-6acd-5560-bd37-59dd1a063e63"}, {"title": "袁琦等十一人被处死，明廷张榜公布罪名", "description": "宣德六年十二月乙未，袁琦等十一人被处死。朝廷张榜公布他们的罪名。", "start_year": 1432, "end_year": 1432, "time_original": "宣德六年十二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e30f5bb3-bea1-5816-b9a6-d7227f24f748"}, {"title": "金幼孜去世", "description": "宣德6年（1431年）十二月，金幼孜去世。", "start_year": 1431, "end_year": 1431, "time_original": "宣德6年（1431年）十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "208715c8-6ed8-552e-990f-17ad00175069"}, {"title": "明廷派御史巡视宁夏、甘州屯田水利", "description": "宣德六年十二月庚戌，朝廷派御史巡视宁夏和甘州的屯田与水利事务。", "start_year": 1432, "end_year": 1432, "time_original": "宣德六年十二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "83169a8e-3dbe-526a-a930-d8757470f585"}, {"title": "本纪汇记宣德六年多地入贡", "description": "宣德六年，占城、琉球、瓦剌、哈密、苏门答剌和亦力把里入贡。 按原历纪年，事情发生在公元1431至1432年之间。", "start_year": null, "end_year": null, "time_original": "宣德六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "456f48ac-f689-5753-a17b-504cf58cdfc5"}, {"title": "本纪记初一日食，明廷取消朝贺", "description": "宣德七年正月初一，发生日食，朝廷取消朝贺。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年正月辛酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8eb2ca23-12e2-5605-95f0-c1e063a1777c"}, {"title": "明宣宗在南郊祭祀天地", "description": "宣德七年正月癸酉，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年正月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96dfba7e-9d18-57c5-ad6e-b8ed0f1dc294"}, {"title": "明宣宗命司法官署审录在押囚犯", "description": "宣德七年二月甲午，春天气候转暖，明宣宗朱瞻基命主管司法的官署审录在押囚犯。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年二月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "276e701d-06e8-521e-874c-80af5643fd78"}, {"title": "明廷下诏施行宽恤政策", "description": "宣德七年三月庚申，朝廷下诏推行减轻民众负担的宽恤政策。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年三月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e6739ebb-a11a-5d5f-9772-07ca42ec0dfb"}, {"title": "明宣宗要求落实官田减税诏令", "description": "宣德七年三月辛酉，明宣宗告谕礼部，官田赋税重，已命减去三成。他听说先前免租命令没有得到户部执行，明确要求各司今后落实诏令。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年三月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5134aba9-18dd-53e6-8dd7-c8664b1de0d9"}, {"title": "明廷免除山西积欠的赋税", "description": "宣德七年四月辛丑，朝廷免除山西积欠的赋税。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年四月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1142daf7-6adb-5de6-8b09-063ea862a102"}, {"title": "明廷招募商人向边地运粮并办理盐引", "description": "宣德七年四月壬寅，朝廷招募商人按中盐办法向边地输送粮食。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年四月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be1e8acb-7dc6-527e-b1dd-eda56ecbbd85"}, {"title": "明廷审录在押囚犯", "description": "宣德七年六月癸卯，朝廷审录在押囚犯。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年六月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c73f4da1-e77a-508c-8e90-dba96db9e904"}, {"title": "明廷叫停由宦官赴外地买马", "description": "宣德七年六月癸丑，朝廷停止派宦官到本纪所称番地采购马匹。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年六月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09d40baf-9f4a-5b80-951c-4a8865bb17a7"}, {"title": "三十五篇《官箴》完成并发给百官", "description": "宣德七年六月，三十五篇《官箴》完成，朝廷将它们发给百官阅看。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82a510a3-3d03-55ee-80bc-fd8fdd590de4"}, {"title": "明廷命高级京官荐才并罢黜不称职的地方官", "description": "宣德七年八月乙未，朝廷命三品以上京官举荐有才干、品行和学问的人，并令吏部和都察院罢黜不称职的地方官员。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年八月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19accf82-770e-5623-b5c9-c067755120a5"}, {"title": "明廷命诸将巡视边境", "description": "宣德七年九月庚午，明廷诸将巡视边境。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年九月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7280547c-e748-573a-9c1b-e58321d1d120"}, {"title": "明廷减免两畿与嘉兴、湖州灾税", "description": "宣德七年秋，朝廷免除两畿及嘉兴、湖州水灾所涉税粮。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年秋", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb7fe52b-e589-5aa2-b971-1fe34a1f494a"}, {"title": "明廷召陈瑄、赵新等年底进京讨论粮赋", "description": "宣德七年十一月辛酉，朝廷召督办漕运的平江伯陈瑄、侍郎赵新等人在年底到京，商议粮赋事务利弊。", "start_year": 1432, "end_year": 1432, "time_original": "宣德七年十一月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5b3fe46-96e0-55a9-826f-e9eae1c04213"}, {"title": "本纪汇记宣德七年多地入贡", "description": "宣德七年，占城、琉球、哈密、哈烈、瓦剌、亦力把里入贡。 按原历纪年，事情发生在公元1432至1433年之间。", "start_year": null, "end_year": null, "time_original": "宣德七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7f26e662-2ca2-5870-b9d0-5ade8dfbd891"}]'::jsonb)
